import { createGlobalStyle } from 'antd-style'

export const GlobalStyle = createGlobalStyle(({ theme: token }) => {
  return {
    '.dnd--dragging': {
      cursor: 'move'
    },

    '.dnd--invalid': {
      '.dnd__overlay': {
        background: token.colorErrorBg,
        color: token.colorErrorActive
      }
    }
  }
})
